"""Leaf LUT spec: the 256-entry E2M1 x E2M1 product table as a SystemVerilog case statement.

Generated from cimfp4.formats.tables (the same table every golden model uses) and used as the
reference side of the formal miter against rtl/src/leaf_unit.sv (tb/formal/leaf_dec_equiv.ys).
"""

from __future__ import annotations

from ..formats.tables import PRODUCT_X4


def emit_leaf_spec_sv(name: str = "leaf_spec") -> str:
    lines = [
        "// AUTO-GENERATED by cimfp4.rtlgen.leaf_spec — DO NOT EDIT (formal reference only).",
        f"module {name} (",
        "  input  logic [3:0] w,",
        "  input  logic [3:0] x,",
        "  output logic [7:0] mag,",
        "  output logic       s,",
        "  output logic [8:0] oc",
        ");",
        "  assign oc = s ? ~{1'b0, mag} : {1'b0, mag};",
        "  always_comb begin",
        "    unique case ({w, x})",
    ]
    for w in range(16):
        for x in range(16):
            p = int(PRODUCT_X4[w, x])
            lines.append(f"      8'h{w:x}{x:x}: begin mag = 8'd{abs(p)}; s = 1'b{int(p < 0)}; end")
    lines += [
        "      default: begin mag = 8'd0; s = 1'b0; end",
        "    endcase",
        "  end",
        f"endmodule : {name}",
        "",
    ]
    return "\n".join(lines)
